import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";
import ManagerTripApprovals from './ManagerTripApprovals';

const api = axios.create({ baseURL: "http://localhost:8000" });
api.interceptors.request.use((config) => { const token = localStorage.getItem("token"); if (token) config.headers.Authorization = `Bearer ${token}`; return config; });

function ManagerDashboardNew() {
  const navigate = useNavigate();
  const [profile, setProfile] = useState(null);
  const [employees, setEmployees] = useState([]);
  const [allEmployees, setAllEmployees] = useState([]);
  const [pendingBills, setPendingBills] = useState([]);
  const [statistics, setStatistics] = useState({});
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState('overview');
  const [message, setMessage] = useState("");
  const [searchTerm, setSearchTerm] = useState("");
  const [departmentFilter, setDepartmentFilter] = useState("");
  const [selectedEmployee, setSelectedEmployee] = useState(null);
  const [employeeBills, setEmployeeBills] = useState([]);
  const [showEmployeeModal, setShowEmployeeModal] = useState(false);

  useEffect(() => {
    const token = localStorage.getItem("token");
    if (!token) { navigate("/login"); return; }
    fetchProfile();
    fetchData();
  }, [navigate]);

  const fetchProfile = async () => {
    try {
      const res = await api.get("/profile");
      setProfile(res.data);
      if (res.data.role !== 'manager') navigate("/upload");
    } catch (err) {
      if (err.response?.status === 401) { localStorage.removeItem("token"); navigate("/login"); }
    }
  };

  const fetchData = async () => {
    setLoading(true);
    try { await Promise.all([fetchTeamEmployees(), fetchAllEmployees(), fetchPendingBills(), fetchStatistics()]); }
    catch (err) { console.error("Error fetching data:", err); }
    finally { setLoading(false); }
  };

  const fetchTeamEmployees = async () => { try { const res = await api.get("/manager/team-overview"); setEmployees(res.data || []); } catch (err) { showMessage("Failed to fetch team employees", true); } };
  const fetchAllEmployees = async () => { try { const res = await api.get("/manager/all-employees"); setAllEmployees(res.data || []); } catch { try { const fallback = await api.get("/manager/team-overview"); setAllEmployees(fallback.data || []); } catch {} } };
  const fetchPendingBills = async () => { try { const res = await api.get("/manager/pending-bills?page=1&page_size=20"); setPendingBills(res.data.bills || []); } catch {} };
  const fetchStatistics = async () => { try { const res = await api.get("/manager/statistics"); setStatistics(res.data || {}); } catch {} };
  const fetchEmployeeBills = async (employeeId) => { try { const res = await api.get(`/manager/employee/${employeeId}/bills?page=1&page_size=50`); setEmployeeBills(res.data.bills || []); } catch { showMessage("Failed to fetch employee bills", true); } };

  const approveBill = async (billId) => { try { await api.put(`/bills/${billId}/status`, { status: "approved" }); showMessage("Bill approved successfully!"); fetchPendingBills(); fetchStatistics(); } catch (err) { showMessage(err.response?.data?.detail || "Failed to approve bill.", true); } };
  const rejectBill = async (billId) => { try { await api.put(`/bills/${billId}/status`, { status: "rejected" }); showMessage("Bill rejected successfully!"); fetchPendingBills(); fetchStatistics(); } catch (err) { showMessage(err.response?.data?.detail || "Failed to reject bill.", true); } };

  const showMessage = (msg, isError = false) => { setMessage(msg); setTimeout(() => setMessage(""), isError ? 7000 : 5000); };
  const logout = () => { localStorage.removeItem("token"); navigate("/login"); };
  const goToProfile = () => navigate("/profile");
  const handleTabChange = (tab) => setActiveTab(tab);

  const handleEmployeeSelect = (employee) => { setSelectedEmployee(employee); setShowEmployeeModal(true); fetchEmployeeBills(employee.postgres_id || employee.id); };
  const closeEmployeeModal = () => { setShowEmployeeModal(false); setSelectedEmployee(null); setEmployeeBills([]); };

  const filteredEmployees = allEmployees.filter(employee => {
    const matchesSearch = !searchTerm || employee.name?.toLowerCase().includes(searchTerm.toLowerCase()) || employee.username?.toLowerCase().includes(searchTerm.toLowerCase()) || employee.email?.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesDepartment = !departmentFilter || employee.department?.toLowerCase().includes(departmentFilter.toLowerCase());
    return matchesSearch && matchesDepartment;
  });
  const departments = [...new Set(allEmployees.map(emp => emp.department).filter(Boolean))];
  const formatCurrency = (amount, currency = 'USD') => amount == null ? 'N/A' : new Intl.NumberFormat('en-US', { style: 'currency', currency }).format(amount);
  const formatDate = (s) => { if (!s) return 'N/A'; try { return new Date(s).toLocaleDateString(); } catch { return s; } };
  const getStatusColor = (status) => ({ approved: '#28a745', rejected: '#dc3545', under_review: '#ffc107' }[status] || '#6c757d');

  const LoadingSpinner = () => (<div className="loading-spinner"><div className="spinner"></div></div>);
  const getMessageClass = () => (!message ? "" : (message.toLowerCase().includes("error") || message.toLowerCase().includes("failed")) ? "message error" : "message success");

  if (loading) return (
    <div className="container-page"><div className="content-card loading-container"><LoadingSpinner /><h3>Loading Manager Dashboard...</h3></div></div>
  );

  return (
    <div className="container-page">
      <div className="page-header">
        <div className="title">Manager Dashboard</div>
        <div className="subtitle">Employee Management & Bill Oversight</div>
      </div>

      {message && (<div className={`message ${getMessageClass()}`}>{message}</div>)}

      {/* Stats */}
      <div className="stats-dashboard section">
        <div className="stats-grid">
          <div className="stat-card primary"><div className="stat-icon">👥</div><div className="stat-content"><h3>Total Employees</h3><div className="stat-value">{allEmployees.length}</div><div className="stat-label">Under Management</div></div></div>
          <div className="stat-card success"><div className="stat-icon">📄</div><div className="stat-content"><h3>Total Bills</h3><div className="stat-value">{statistics.total_bills || 0}</div><div className="stat-label">All Submissions</div></div></div>
          <div className="stat-card warning"><div className="stat-icon">⏳</div><div className="stat-content"><h3>Pending Approval</h3><div className="stat-value">{pendingBills.length}</div><div className="stat-label">Awaiting Review</div></div></div>
          <div className="stat-card info"><div className="stat-icon">💰</div><div className="stat-content"><h3>Total Amount</h3><div className="stat-value">{formatCurrency(statistics.total_amount || 0)}</div><div className="stat-label">All Bills</div></div></div>
        </div>
      </div>

      {/* Tabs */}
      <div className="manager-tabs">
        <button className={`tab ${activeTab === 'overview' ? 'active' : ''}`} onClick={() => handleTabChange('overview')}><i className="icon-users"></i> Employee Overview</button>
        <button className={`tab ${activeTab === 'employees' ? 'active' : ''}`} onClick={() => handleTabChange('employees')}><i className="icon-list"></i> All Employees</button>
        <button className={`tab ${activeTab === 'pending' ? 'active' : ''}`} onClick={() => handleTabChange('pending')}><i className="icon-clock"></i> Pending Bills ({pendingBills.length})</button>
        <button className={`tab ${activeTab === 'trip-approvals' ? 'active' : ''}`} onClick={() => handleTabChange('trip-approvals')}><i className="icon-plane"></i> Trip Approvals</button>
      </div>

      {/* Content */}
      <div className="tab-content">
        {activeTab === 'overview' && (
          <div className="content-card">
            <div className="page-title">Team Overview</div>
            {employees.length > 0 ? (
              <div className="employee-grid">
                {employees.map((employee) => (
                  <div key={employee.id} className="employee-card card-hover">
                    <div className="employee-header">
                      <h4 className="employee-name">{employee.name || employee.username}</h4>
                      <span className="employee-email">{employee.email}</span>
                    </div>
                    <div className="employee-stats">
                      <div className="stat-row"><span>Username:</span><span>{employee.username || 'N/A'}</span></div>
                      <div className="stat-row"><span>Department:</span><span>{employee.department || 'N/A'}</span></div>
                      <div className="stat-row"><span>Registration Date:</span><span>{formatDate(employee.registration_date)}</span></div>
                      <div className="stat-row"><span>Total Bills:</span><span>{employee.total_bills || 0}</span></div>
                      <div className="stat-row"><span>Total Amount:</span><span>{formatCurrency(employee.total_amount || 0)}</span></div>
                      <div className="stat-row"><span>Pending:</span><span className="pending-count">{employee.pending_bills || 0}</span></div>
                    </div>
                    <button className="btn btn-primary btn-small" onClick={() => handleEmployeeSelect(employee)}>View Bills</button>
                  </div>
                ))}
              </div>
            ) : (
              <p className="text-muted">No employees found under your management.</p>
            )}
          </div>
        )}

        {activeTab === 'employees' && (
          <div className="content-card">
            <div className="page-title">All Employees</div>
            <div className="action-buttons" style={{ marginBottom: 12 }}>
              <input className="form-control" placeholder="Search name/username/email" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} />
              <select className="form-control" value={departmentFilter} onChange={(e) => setDepartmentFilter(e.target.value)}>
                <option value="">All Departments</option>
                {departments.map((d) => (<option key={d} value={d}>{d}</option>))}
              </select>
            </div>
            <div className="employee-grid">
              {filteredEmployees.map((employee) => (
                <div key={employee.id} className="employee-card card-hover">
                  <div className="employee-header">
                    <h4 className="employee-name">{employee.name || employee.username}</h4>
                    <span className="employee-email">{employee.email}</span>
                  </div>
                  <div className="employee-stats">
                    <div className="stat-row"><span>Department:</span><span>{employee.department || 'N/A'}</span></div>
                    <div className="stat-row"><span>Total Bills:</span><span>{employee.total_bills || 0}</span></div>
                    <div className="stat-row"><span>Pending:</span><span className="pending-count">{employee.pending_bills || 0}</span></div>
                  </div>
                  <button className="btn btn-primary btn-small" onClick={() => handleEmployeeSelect(employee)}>View Bills</button>
                </div>
              ))}
            </div>
          </div>
        )}

        {activeTab === 'pending' && (
          <div className="content-card">
            <div className="page-title">Pending Bills for Approval</div>
            {pendingBills.length > 0 ? (
              <div className="bills-list">
                {pendingBills.map((bill) => (
                  <div key={bill.id} className="bill-item pending-bill card-hover">
                    <div className="bill-header-item">
                      <div>
                        <h4>Bill #{bill.id}</h4>
                        <p className="employee-info">{bill.employee_name} ({bill.employee_email})</p>
                      </div>
                      <div className="bill-actions">
                        <button className="btn btn-primary btn-small" onClick={() => approveBill(bill.id)}>✓ Approve</button>
                        <button className="btn btn-danger btn-small" onClick={() => rejectBill(bill.id)}>✗ Reject</button>
                      </div>
                    </div>
                    <div className="bill-details-grid">
                      <div><strong>Amount:</strong> {formatCurrency(bill.amount)}</div>
                      <div><strong>Date:</strong> {formatDate(bill.date)}</div>
                      <div><strong>Vendor:</strong> {bill.vendor || 'N/A'}</div>
                      <div><strong>Category:</strong> {bill.category || 'N/A'}</div>
                      <div><strong>Submitted:</strong> {formatDate(bill.created_at)}</div>
                      <div><strong>File:</strong> {bill.filename || 'N/A'}</div>
                    </div>
                    {bill.remarks && (<div className="bill-remarks">Remarks: {bill.remarks}</div>)}
                  </div>
                ))}
              </div>
            ) : (
              <p className="text-muted">No pending bills right now.</p>
            )}
          </div>
        )}

        {activeTab === 'trip-approvals' && (
          <div className="content-card">
            <ManagerTripApprovals />
          </div>
        )}
      </div>

      {showEmployeeModal && (
        <div className="modal-overlay" onClick={closeEmployeeModal}>
          <div className="modal" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header"><h3>Employee Bills</h3><button className="close-btn" onClick={closeEmployeeModal}>×</button></div>
            <div className="modal-body">
              {selectedEmployee && (
                <div className="content-card" style={{ marginBottom: 12 }}>
                  <div className="page-title">{selectedEmployee.name || selectedEmployee.username}</div>
                  <div className="text-muted">{selectedEmployee.email}</div>
                </div>
              )}
              <div className="bills-list">
                {employeeBills.map((bill) => (
                  <div key={bill.id} className="bill-item card-hover">
                    <div className="grid" style={{ gridTemplateColumns: '1fr auto' }}>
                      <div><strong>Bill #{bill.id}</strong></div>
                      <span className="badge" style={{ backgroundColor: getStatusColor(bill.status) }}>{bill.status.toUpperCase()}</span>
                    </div>
                    <div className="bill-details-grid" style={{ marginTop: 8 }}>
                      <div><strong>Amount:</strong> {formatCurrency(bill.amount)}</div>
                      <div><strong>Date:</strong> {formatDate(bill.date)}</div>
                      <div><strong>Vendor:</strong> {bill.vendor || 'N/A'}</div>
                      <div><strong>Category:</strong> {bill.category || 'N/A'}</div>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default ManagerDashboardNew;
